import 'dart:convert';
import 'dart:io';
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:excel/excel.dart' as xl;
import 'package:path_provider/path_provider.dart';
import 'package:share_plus/share_plus.dart';
import 'package:file_picker/file_picker.dart';

const bg=Color(0xff0B1120),panel=Color(0xff151E2E),teal=Color(0xff2DD4BF),blue=Color(0xff38BDF8);
void main()=>runApp(const MaterialApp(debugShowCheckedModeBanner:false,home:CostApp()));
double? parse(String v)=>double.tryParse(v.trim().replaceAll(',','.'));
String euro(double n)=>'€ ${n.toStringAsFixed(2).replaceAll('.',',')}';
class Filament {Filament(this.name,this.price); String name; double price;}
class CostApp extends StatefulWidget {const CostApp({super.key}); @override State<CostApp> createState()=>_CostState();}
class _CostState extends State<CostApp>{
 final grams=TextEditingController(),hours=TextEditingController(text:'0'),minutes=TextEditingController(text:'0'),energy=TextEditingController(text:'0,15'),power=TextEditingController(text:'200');
 List<Filament> filaments=[]; String? selected; int tab=0; bool english=false; double? material,kwh,electric,total;
 String tr(String it,String en)=>english?en:it;
 @override void initState(){super.initState();load();}
 Future<void> load()async{final p=await SharedPreferences.getInstance();try{filaments=(jsonDecode(p.getString('filaments')??'[]') as List).map((x)=>Filament(x['name'] as String,(x['price'] as num).toDouble())).toList();}catch(_){filaments=[];}energy.text=p.getString('energy')??'0,15';power.text=p.getString('power')??'200';english=p.getBool('english')??false;if(filaments.isNotEmpty)selected=filaments.first.name;if(mounted)setState((){});}
 Future<void> save()async{final p=await SharedPreferences.getInstance();await p.setString('filaments',jsonEncode(filaments.map((f)=>{'name':f.name,'price':f.price}).toList()));await p.setString('energy',energy.text);await p.setString('power',power.text);await p.setBool('english',english);}
 void msg(String s)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));
 Widget field(String title,TextEditingController c)=>TextField(controller:c,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:InputDecoration(labelText:title,border:const OutlineInputBorder()));
 Widget card(String title,Widget child)=>Card(color:panel,margin:const EdgeInsets.only(bottom:14),child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontSize:17,fontWeight:FontWeight.bold)),const SizedBox(height:14),child])));
 Widget btn(String title,VoidCallback fn)=>SizedBox(width:double.infinity,child:FilledButton(style:FilledButton.styleFrom(backgroundColor:teal,foregroundColor:bg),onPressed:fn,child:Padding(padding:const EdgeInsets.all(9),child:Text(title))));
 void calculate(){final g=parse(grams.text),h=parse(hours.text),m=parse(minutes.text),e=parse(energy.text),w=parse(power.text);if(selected==null||[g,h,m,e,w].any((x)=>x==null||!x!.isFinite||x<0)||m!>=60){msg(tr('Controlla i dati e seleziona un filamento.','Check inputs and select a filament.'));return;}final f=filaments.firstWhere((x)=>x.name==selected);setState((){material=g!/1000*f.price;kwh=w!/1000*(h!+m!/60);electric=kwh!*e!;total=material!+electric!;});}
 Future<void> export()async{if(total==null){msg(tr('Calcola prima il costo.','Calculate cost first.'));return;}try{
 final append=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text(tr('Esportazione Excel','Excel export')),content:Text(tr('Aggiungere a un file esistente?','Append to an existing file?')),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:Text(tr('Nuovo','New'))),TextButton(onPressed:()=>Navigator.pop(c,true),child:Text(tr('Esistente','Existing')))]));if(append==null)return;
 xl.Excel book; if(append){final pick=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['xlsx'],withData:true);if(pick==null)return;final bytes=pick.files.single.bytes??await File(pick.files.single.path!).readAsBytes();book=xl.Excel.decodeBytes(bytes);}else{book=xl.Excel.createExcel();}
 final name=english?'Print summary':'Riepilogo stampa';final sheet=book.sheets[name]??book[book.getDefaultSheet()??'Sheet1'];
 final heads=['Plate','Date/Time','Filament','Total filament (g)','Filament price (€/kg)','Print hours','Average power (W)','Estimated energy (kWh)','Electricity price (€/kWh)','Filament cost (€)','Electricity cost (€)','Total plate cost (€)'];
 if(sheet.maxRows==0){sheet.appendRow(heads.map((v)=>xl.TextCellValue(v)).toList());}
 final f=filaments.firstWhere((x)=>x.name==selected);final count=sheet.maxRows;sheet.appendRow([xl.IntCellValue(count),xl.TextCellValue(DateTime.now().toIso8601String()),xl.TextCellValue(f.name),xl.DoubleCellValue(parse(grams.text)!),xl.DoubleCellValue(f.price),xl.DoubleCellValue(parse(hours.text)!+parse(minutes.text)!/60),xl.DoubleCellValue(parse(power.text)!),xl.DoubleCellValue(kwh!),xl.DoubleCellValue(parse(energy.text)!),xl.DoubleCellValue(material!),xl.DoubleCellValue(electric!),xl.DoubleCellValue(total!)]);
 final bytes=book.encode();if(bytes==null)throw Exception('Excel encoding');final dir=await getTemporaryDirectory();final file=File('${dir.path}/3d_print_cost_summary.xlsx');await file.writeAsBytes(bytes,flush:true);await Share.shareXFiles([XFile(file.path)]);
 }catch(e){msg('Excel: $e');}}
 Future<void> editFilament([Filament? f])async{final name=TextEditingController(text:f?.name??''),price=TextEditingController(text:f?.price.toString()??'');await showDialog(context:context,builder:(c)=>AlertDialog(title:Text(f==null?tr('Nuovo filamento','New filament'):tr('Modifica filamento','Edit filament')),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Nome / Name')),const SizedBox(height:12),field('€/kg',price)]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),TextButton(onPressed:(){final p=parse(price.text),n=name.text.trim();if(n.isEmpty||p==null||!p.isFinite||p<0||filaments.any((x)=>x.name.toLowerCase()==n.toLowerCase()&&x!=f)){msg(tr('Nome o prezzo non valido','Invalid name or price'));return;}setState((){if(f==null){filaments.add(Filament(n,p));selected??=n;}else{if(selected==f.name)selected=n;f.name=n;f.price=p;}filaments.sort((a,b)=>a.name.toLowerCase().compareTo(b.name.toLowerCase()));total=null;});save();Navigator.pop(c);},child:Text(tr('Salva','Save')))]));}
 Widget calculator()=>ListView(padding:const EdgeInsets.all(16),children:[card(tr('DATI DELLA STAMPA','PRINT DATA'),Column(children:[DropdownButtonFormField<String>(value:selected,decoration:InputDecoration(labelText:tr('Filamento','Filament')),items:filaments.map((f)=>DropdownMenuItem(value:f.name,child:Text(f.name))).toList(),onChanged:(v)=>setState(()=>selected=v)),const SizedBox(height:12),field(tr('Filamento totale (g)','Total filament (g)'),grams),const SizedBox(height:12),Row(children:[Expanded(child:field(tr('Ore','Hours'),hours)),const SizedBox(width:12),Expanded(child:field(tr('Minuti','Minutes'),minutes))]),const SizedBox(height:14),btn(tr('CALCOLA COSTO','CALCULATE COST'),calculate)])),card(tr('RIEPILOGO','SUMMARY'),Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${tr('Costo filamento','Filament cost')}: ${material==null?'—':euro(material!)}'),Text('${tr('Energia stimata','Estimated energy')}: ${kwh==null?'—':'${kwh!.toStringAsFixed(3)} kWh'}'),Text('${tr('Costo corrente','Electricity cost')}: ${electric==null?'—':euro(electric!)}'),const SizedBox(height:16),Text('${tr('COSTO TOTALE','TOTAL COST')}: ${total==null?'—':euro(total!)}',style:const TextStyle(color:teal,fontSize:25,fontWeight:FontWeight.bold)),const SizedBox(height:16),btn(tr('ESPORTA EXCEL','EXPORT EXCEL'),export)]))]);
 Widget filamentPage()=>ListView(padding:const EdgeInsets.all(16),children:[btn(tr('AGGIUNGI FILAMENTO','ADD FILAMENT'),()=>editFilament()),...filaments.map((f)=>Card(color:panel,child:ListTile(title:Text(f.name),subtitle:Text('${euro(f.price)}/kg'),onTap:()=>editFilament(f),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()async{final yes=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text(tr('Eliminare filamento?','Delete filament?')),content:Text(f.name),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('No')),TextButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Yes'))]));if(yes==true){setState((){filaments.remove(f);if(selected==f.name)selected=filaments.isEmpty?null:filaments.first.name;total=null;});save();}})))]); 
 Widget settings()=>ListView(padding:const EdgeInsets.all(16),children:[card(tr('IMPOSTAZIONI','SETTINGS'),Column(children:[field(tr('Costo corrente (€/kWh)','Electricity price (€/kWh)'),energy),const SizedBox(height:14),field(tr('Consumo medio stampante (W)','Average printer power (W)'),power),const SizedBox(height:14),SwitchListTile(title:const Text('English'),value:english,onChanged:(v){setState(()=>english=v);save();}),btn(tr('SALVA IMPOSTAZIONI','SAVE SETTINGS'),(){final e=parse(energy.text),w=parse(power.text);if(e==null||w==null||!e.isFinite||!w.isFinite||e<0||w<0){msg(tr('Valori non validi','Invalid values'));return;}save();setState(()=>total=null);msg(tr('Impostazioni salvate','Settings saved'));})]))]);
 @override Widget build(BuildContext context)=>Theme(data:ThemeData(useMaterial3:true,brightness:Brightness.dark,scaffoldBackgroundColor:bg,colorScheme:ColorScheme.fromSeed(seedColor:teal,brightness:Brightness.dark)),child:Scaffold(appBar:AppBar(backgroundColor:bg,title:const Text('3D PRINT COST',style:TextStyle(fontWeight:FontWeight.bold)),bottom:PreferredSize(preferredSize:const Size.fromHeight(3),child:Container(height:3,color:teal))),body:[calculator(),filamentPage(),settings()][tab],bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:[NavigationDestination(icon:const Icon(Icons.calculate_outlined),label:tr('Calcolo','Calculator')),NavigationDestination(icon:const Icon(Icons.inventory_2_outlined),label:tr('Filamenti','Filaments')),NavigationDestination(icon:const Icon(Icons.settings_outlined),label:tr('Impostazioni','Settings'))])));
}
